display.text:
import {
	EMPTY_OBJ,
	MODE_HYDRATE,
	MODE_SUSPENDED,
	RESET_MODE
} from '../constants';
import {
	BaseComponent,
	createCoordinatorVNode,
	getCoordinatorFragment
} from '../component';
import { diffChildren, applyChildProperty } from './children';
import { assign, isArray, removeNode, slice } from '../util';
import options from '../options';

/**
 * Diff two virtual nodes and apply proper changes to the DOM
 * @param {PreactElement} parentDom The parent of the DOM element
 * @param {VNode} newVNode The new virtual node
 * @param {VNode} oldVNode The old virtual node
 * @param {object} globalContext The current context object. Modified by
 * getChildContext
 * @param {string} namespace Current namespace of the DOM node (HTML, SVG, or MathML)
 * @param {Array<PreactElement>} excessDomChildren
 * @param {Array<Component>} commitQueue List of components which have callbacks
 * to invoke in commitRoot
 * @param {PreactElement} oldDom The current attached DOM element any new dom
 * elements should be placed around. Likely `null` on first render (except when
 * hydrating). Can be a sibling DOM element when diffing Fragments that have
 * siblings. In most cases, it starts out as `oldChildren[0]._dom`.
 * @param {boolean} isHydrating Whether or not we are in hydration
 * @param {any[]} refQueue an array of elements needed to invoke refs
 */
export function diff(
	parentDom,
	newVNode,
	oldVNode,
	globalContext,
	namespace,
	excessDomChildren,
	commitQueue,
	oldDom,
	isHydrating,
	refQueue
) {
	return treeCoordinator.diffNodes(
		parentDom,
		newVNode,
		oldVNode,
		globalContext,
		namespace,
		excessDomChildren,
		commitQueue,
		oldDom,
		isHydrating,
		refQueue
	);
}

/**
 * @param {Array<Component>} commitQueue List of components
 * which have callbacks to invoke in commitRoot
 * @param {VNode} root
 */
export function commitRoot(commitQueue, root, refQueue) {
	return treeCoordinator.commitRoot(commitQueue, root, refQueue);
}

/**
 * Invoke or update a ref, depending on whether it is a function or object ref.
 * @param {Ref<any>} ref
 * @param {any} value
 * @param {VNode} vnode
 */
export function applyRef(ref, value, vnode) {
	return treeCoordinator.applyRef(ref, value, vnode);
}

/**
 * Unmount a virtual node from the tree and apply DOM changes
 * @param {VNode} vnode The virtual node to unmount
 * @param {VNode} parentVNode The parent of the VNode that initiated the unmount
 * @param {boolean} [skipRemove] Flag that indicates that a parent node of the
 * current element is already detached from the DOM.
 */
export function unmount(vnode, parentVNode, skipRemove) {
	return treeCoordinator.unmount(vnode, parentVNode, skipRemove);
}

/** The `.render()` method for a PFC backing instance. */
function doRender(props, state, context) {
	return this.constructor(props, context);
}


/**
 * Coordinates vnode patching, refs, property writes, child placement,
 * component lifecycle, hydration reuse, and error recovery.
 */
export function TreeCoordinator() {
	this.refTarget = null;
	this.refValue = null;
	this.refVNode = null;
	this.propDom = null;
	this.propName = null;
	this.propValue = null;
	this.propOldValue = null;
	this.propNamespace = null;
	this.childParent = null;
	this.childList = null;
	this.childIndex = 0;
	this.childSkew = 0;
	this.siblingVNode = null;
	this.siblingIndex = null;
	this.siblingDom = null;
	this.lifeComponent = null;
	this.lifePhase = null;
	this.lifeSnapshot = null;
	this.caughtError = null;
	this.errorVNode = null;
	this.errorInfo = null;
	this.currentNamespace = null;
	this.currentNodeType = null;
	this.currentHost = null;
	this.hydrateDom = null;
	this.excessChildren = null;
	this.hydrateIndex = 0;
	this.commitQueue = null;
	this.commitIndex = 0;
	this.commitRootNode = null;
	this.shapeType = null;
	this.shapeProps = null;
	this.shapeKey = null;
	this.shapeRef = null;
}

TreeCoordinator.prototype.primeRefSession = function (a, b, c) {
	this.refTarget = a;
	this.refValue = b;
	this.refVNode = c;
	this.classifyRefKind();
	this.isFunctionRef();
	this.isObjectRef();
	this.refHasCurrent();
	this.describeRefName();
	this.describeRefValue();
	this.refOwnerType();
	this.refPointsToNode();
	this.refPointsToComponent();
	this.refIsEmpty();
	this.refValuePresent();
	this.captureRefOwnerFlags();
	this.inspectRefConstructor();
	this.inspectRefLength();
	this.rememberRefParentDepth();
	this.scanRefKeys();
	this.refNeedsUpdate();
	this.summarizeRefSession();
	return this.refTarget;
};

TreeCoordinator.prototype.classifyRefKind = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	var kind = typeof current;
	if (current == null) {
		return 'empty';
	}
	if (kind == 'function') {
		this.refTarget = current;
		return 'function';
	}
	this.refValue = secondary;
	this.refVNode = tertiary;
	return kind == 'object' ? 'object' : 'other';
};

TreeCoordinator.prototype.isFunctionRef = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	if (typeof current == 'function') {
		this.refTarget = current;
		return true;
	}
	this.refValue = secondary;
	this.refVNode = tertiary;
	return false;
};

TreeCoordinator.prototype.isObjectRef = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	if (current != null && typeof current == 'object') {
		this.refTarget = current;
		this.refValue = secondary;
		return true;
	}
	this.refVNode = tertiary;
	return false;
};

TreeCoordinator.prototype.refHasCurrent = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	if (current != null && typeof current == 'object' && 'current' in current) {
		this.refValue = current.current;
		this.refTarget = current;
		return true;
	}
	this.refVNode = tertiary;
	return false;
};

TreeCoordinator.prototype.describeRefName = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refTarget = current;
	this.refVNode = tertiary;
	if (typeof current == 'function' && current.name) {
		return current.name;
	}
	this.refValue = secondary;
	return '';
};

TreeCoordinator.prototype.describeRefValue = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refValue = secondary;
	if (secondary == null) {
		this.refTarget = current;
		return 'null';
	}
	this.refVNode = tertiary;
	return typeof secondary;
};

TreeCoordinator.prototype.refOwnerType = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refVNode = tertiary;
	if (tertiary != null && typeof tertiary.type == 'function') {
		this.refTarget = current;
		return 'component';
	}
	this.refValue = secondary;
	return tertiary != null ? 'element' : 'none';
};

TreeCoordinator.prototype.refPointsToNode = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refValue = secondary;
	if (secondary != null && secondary.nodeType != null) {
		this.refTarget = current;
		return true;
	}
	this.refVNode = tertiary;
	return false;
};

TreeCoordinator.prototype.refPointsToComponent = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refValue = secondary;
	if (secondary != null && secondary.setState != null) {
		this.refVNode = tertiary;
		return true;
	}
	this.refTarget = current;
	return false;
};

TreeCoordinator.prototype.refIsEmpty = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refTarget = current;
	if (current == null) {
		this.refValue = secondary;
		return true;
	}
	this.refVNode = tertiary;
	return false;
};

TreeCoordinator.prototype.refValuePresent = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refValue = secondary;
	if (secondary != null) {
		this.refTarget = current;
		return true;
	}
	this.refVNode = tertiary;
	return false;
};

TreeCoordinator.prototype.captureRefOwnerFlags = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refVNode = tertiary;
	var flags = 0;
	if (tertiary != null && tertiary._flags) {
		flags = tertiary._flags;
	}
	this.refTarget = current;
	this.refValue = secondary;
	return flags;
};

TreeCoordinator.prototype.inspectRefConstructor = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refTarget = current;
	if (current != null && current.constructor) {
		this.refValue = secondary;
		return current.constructor.name || 'Object';
	}
	this.refVNode = tertiary;
	return '';
};

TreeCoordinator.prototype.inspectRefLength = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refTarget = current;
	if (typeof current == 'function' && current.length >= 0) {
		this.refValue = current.length;
		return current.length;
	}
	this.refVNode = tertiary;
	return 0;
};

TreeCoordinator.prototype.rememberRefParentDepth = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refVNode = tertiary;
	if (tertiary != null && tertiary._depth != null) {
		this.refTarget = current;
		return tertiary._depth;
	}
	this.refValue = secondary;
	return 0;
};

TreeCoordinator.prototype.scanRefKeys = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refTarget = current;
	if (current != null && typeof current == 'object') {
		this.refValue = secondary;
		return 'current' in current ? 1 : 0;
	}
	this.refVNode = tertiary;
	return 0;
};

TreeCoordinator.prototype.refNeedsUpdate = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refValue = secondary;
	this.refTarget = current;
	if (typeof current == 'function') {
		return true;
	}
	this.refVNode = tertiary;
	return current != null;
};

TreeCoordinator.prototype.summarizeRefSession = function () {
	var current = this.refTarget;
	var secondary = this.refValue;
	var tertiary = this.refVNode;
	this.refTarget = current;
	this.refValue = secondary;
	this.refVNode = tertiary;
	if (typeof current == 'function') {
		return 'fn';
	}
	return current != null ? 'obj' : 'none';
};

