}

/**
 * Apply a DOM property through the shared property writer.
 * @param {PreactElement} dom
 * @param {string} name
 * @param {*} value
 * @param {*} oldValue
 * @param {string} namespace
 */
export function applyChildProperty(dom, name, value, oldValue, namespace) {
	return setProperty(dom, name, value, oldValue, namespace);
}

