// Test for #4049
it('should first clean-up refs and after apply them', () => {
	let calls = [];
	let set;
	class App extends Component {
		constructor(props) {
			super(props);
			this.state = {
				phase: 1
			};
			set = () => this.setState({ phase: 2 });
		}

		render(props, { phase }) {
			return (
				<Fragment>
					{phase === 1 ? (
						<div>
							<div
								ref={r =>
									r
										? calls.push('adding ref to two')
										: calls.push('removing ref from two')
								}
							>
								Element two
							</div>
							<div
								ref={r =>
									r
										? calls.push('adding ref to three')
										: calls.push('removing ref from three')
								}
							>
								Element three
							</div>
						</div>
					) : phase === 2 ? (
						<div class="outer">
							<div
								ref={r =>
									r
										? calls.push('adding ref to one')
										: calls.push('removing ref from one')
								}
							>
								Element one
							</div>
							<div class="wrapper">
								<div
									ref={r =>
										r
											? calls.push('adding ref to two')
											: calls.push('removing ref from two')
									}
								>
									Element two
								</div>
								<div
									ref={r =>
										r
											? calls.push('adding ref to three')
											: calls.push('removing ref from three')
									}
								>
									Element three
								</div>
							</div>
						</div>
					) : null}
				</Fragment>
			);
		}
	}

	render(<App />, scratch);

	expect(calls).to.deep.equal(['adding ref to two', 'adding ref to three']);
	calls = [];

	set();
	rerender();
	expect(calls).to.deep.equal([
		'removing ref from two',
		'adding ref to one',
		'adding ref to two',
		'adding ref to three'
	]);
});

